function LongestCommonSubsequence(text1: string, text2: string) -> int {
  let a = text1.chars();
  let b = text2.chars();
  let m = a.length();
  let n = b.length();
  let dp: int[] = [];
  let j = 0;
  while (j <= n) {
    dp.push(0);
    j += 1;
  }
  let i = 1;
  while (i <= m) {
    let prev = 0;
    let k = 1;
    while (k <= n) {
      let temp = dp[k];
      if (a[i - 1] == b[k - 1]) {
        dp[k] = prev + 1;
      } else {
        let up = dp[k];
        let left = dp[k - 1];
        if (left > up) {
          dp[k] = left;
        } else {
          dp[k] = up;
        }
      }
      prev = temp;
      k += 1;
    }
    i += 1;
  }
  return dp[n];
}
